def get_tongue_twisters(difficulty="all", category="all"):
    """Retrieve tongue twisters filtered by difficulty or focus."""
    items = TONGUE_TWISTERS
    diff = (difficulty or "all").lower().strip()
    if diff != "all":
        items = [t for t in items if t.get("difficulty", "").lower() == diff]
    
    cat = (category or "all").lower().strip()
    if cat != "all":
        items = [t for t in items if cat in t.get("focus_sound", "").lower() or cat in t.get("title", "").lower()]
    return items


def get_conversation_scenarios(age_group=None, target_age=21, language="English"):
    """Retrieve all 10 conversation scenarios with localized titles, contexts, and initial greetings."""
    items = []
    norm_lang = (language or "English").strip().title()
    for s in CONVERSATION_SCENARIOS:
        item = dict(s)
        if 'translations' in item and norm_lang in item['translations']:
            trans = item['translations'][norm_lang]
            item['title'] = trans.get('title', item['title'])
            item['context'] = trans.get('context', item['context'])
            item['ai_initial_message'] = trans.get('ai_initial_message', item['ai_initial_message'])
            item['suggested_user_openings'] = trans.get('suggested_user_openings', item['suggested_user_openings'])
        items.append(item)
    return items



